import{_ as c}from"./chunks/ArticleMetadata.Xa7L4Afm.js";import{_ as n,D as d,o as r,c as u,I as s,w as m,k as t,a as p,R as h,b as _,e as f}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const C=JSON.parse('{"title":"项目概览","description":"","frontmatter":{"title":"项目概览","author":"阿源","date":"2026/09/20 10:00","categories":["开源项目"],"tags":["RuoYi","开源项目"],"showArticleMetadata":false},"headers":[],"relativePath":"open-source/01-RuoYi/01-项目概览.md","filePath":"open-source/01-RuoYi/01-项目概览.md","lastUpdated":1789912873000}'),b={name:"open-source/01-RuoYi/01-项目概览.md"},y=t("h1",{id:"项目概览",tabindex:"-1"},[p("项目概览 "),t("a",{class:"header-anchor",href:"#项目概览","aria-label":'Permalink to "项目概览"'},"​")],-1),k=h('<h2 id="本篇目标" tabindex="-1">本篇目标 <a class="header-anchor" href="#本篇目标" aria-label="Permalink to &quot;本篇目标&quot;">​</a></h2><p>先回答三个问题：这个仓库解决什么问题、可运行应用从哪里启动、读一个业务功能时应该沿哪条路径进入源码。完成后，能把前后端边界与后端模块职责说清楚，而不是从文件名开始漫无目的地浏览。</p><h2 id="源码入口" tabindex="-1">源码入口 <a class="header-anchor" href="#源码入口" aria-label="Permalink to &quot;源码入口&quot;">​</a></h2><ul><li><a href="https://gitee.com/y_project/RuoYi-Vue" target="_blank" rel="noreferrer">RuoYi-Vue 项目仓库</a></li><li><a href="https://gitee.com/y_project/RuoYi-Vue/blob/master/pom.xml" target="_blank" rel="noreferrer">根目录 Maven POM</a>：查看聚合工程和模块清单。</li><li><a href="https://gitee.com/y_project/RuoYi-Vue/blob/master/ruoyi-admin/src/main/java/com/ruoyi/RuoYiApplication.java" target="_blank" rel="noreferrer">ruoyi-admin 的 RuoYiApplication.java</a>：查看 Web 服务启动入口。</li><li><a href="https://gitee.com/y_project/RuoYi-Vue/blob/master/ruoyi-admin/pom.xml" target="_blank" rel="noreferrer">ruoyi-admin 模块 POM</a>：查看可运行应用装配了哪些模块。</li></ul><p>RuoYi-Vue 是前后端分离的后台管理系统。阅读时可以把 Vue 管理端的页面与 API 调用视为客户端，把 Java 后端的 Controller、Service 和 Mapper 视为服务端主链路。具体仓库是否同时包含前端源码，要以所用发行包和分支为准。</p><h2 id="调用链或模块关系" tabindex="-1">调用链或模块关系 <a class="header-anchor" href="#调用链或模块关系" aria-label="Permalink to &quot;调用链或模块关系&quot;">​</a></h2><p>从一次页面请求入手，先沿“前端 API 调用 → <code>ruoyi-admin</code> 中的 Controller → 业务 Service → Mapper 与 SQL”向下追踪；再回到 <code>ruoyi-framework</code> 看安全、数据源和 Web 等基础配置，以及 <code>ruoyi-common</code> 提供的通用能力。</p><p>根 POM 将后端拆成多个 Maven 模块：<code>ruoyi-admin</code> 是 Web 应用入口，<code>ruoyi-framework</code> 承载框架配置，<code>ruoyi-system</code> 放置系统业务，<code>ruoyi-quartz</code> 处理定时任务，<code>ruoyi-generator</code> 提供代码生成，<code>ruoyi-common</code> 汇集公共代码。请求路径不一定穿过每个模块；从当前功能实际调用的类和依赖关系确认即可。</p><h2 id="核心实现" tabindex="-1">核心实现 <a class="header-anchor" href="#核心实现" aria-label="Permalink to &quot;核心实现&quot;">​</a></h2><p><code>ruoyi-admin</code> 的启动类位于 <code>com.ruoyi</code> 包下。常见系统功能由 Controller 接收请求，再调用 <code>ruoyi-system</code> 中的业务接口和实现，最后通过 Mapper 访问数据。登录鉴权、异常处理、数据范围等横切行为通常要结合 <code>ruoyi-framework</code> 与 <code>ruoyi-common</code> 一起读，不能只看 Controller 的单个方法。</p><h2 id="我的理解" tabindex="-1">我的理解 <a class="header-anchor" href="#我的理解" aria-label="Permalink to &quot;我的理解&quot;">​</a></h2><p>我把项目拆成两张图来读：Maven 依赖图回答“代码放在哪个模块”，一次请求调用图回答“运行时经过哪些类”。模块名可以帮助缩小范围，但真实的职责边界要由 POM 依赖和实际调用共同验证。</p><h2 id="可验证实验" tabindex="-1">可验证实验 <a class="header-anchor" href="#可验证实验" aria-label="Permalink to &quot;可验证实验&quot;">​</a></h2><ol><li>打开根目录 <code>pom.xml</code>，手动列出 <code>&lt;modules&gt;</code> 中的模块。</li><li>查看 <code>ruoyi-admin/pom.xml</code>，确认 Web 应用依赖的模块；再沿一个 Controller 的注入接口找到 Service 和 Mapper。</li><li>在 IDE 中对一个列表查询设置断点，从 Controller 单步进入 Service，记录 Mapper 方法和对应 SQL 文件。</li></ol><p>以上目录与调用路径以当前阅读版本为参照；不同 RuoYi 版本、分支或二次开发仓库的具体路径和实现可能不同，请以本地 checkout 为准。</p><h2 id="关联笔记与源码链接" tabindex="-1">关联笔记与源码链接 <a class="header-anchor" href="#关联笔记与源码链接" aria-label="Permalink to &quot;关联笔记与源码链接&quot;">​</a></h2><ul><li>下一篇：<a href="/open-source/01-RuoYi/02-目录与模块">目录与模块</a></li><li><a href="/open-source/01-RuoYi/03-启动链路">启动链路</a></li><li><a href="https://gitee.com/y_project/RuoYi-Vue" target="_blank" rel="noreferrer">RuoYi-Vue 仓库</a> · <a href="https://gitee.com/y_project/RuoYi-Vue/blob/master/pom.xml" target="_blank" rel="noreferrer">根目录 Maven POM</a></li></ul>',17);function R(e,P,g,Y,M,V){const i=c,l=d("ClientOnly");return r(),u("div",null,[y,s(l,null,{default:m(()=>{var o,a;return[(((o=e.$frontmatter)==null?void 0:o.aside)??!0)&&(((a=e.$frontmatter)==null?void 0:a.showArticleMetadata)??!0)?(r(),_(i,{key:0,article:e.$frontmatter},null,8,["article"])):f("",!0)]}),_:1}),k])}const S=n(b,[["render",R]]);export{C as __pageData,S as default};
